from collections import deque
from math import sqrt

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def nth_prime(n):
    count = 0
    num = 2
    while True:
        if is_prime(num):
            count += 1
            if count == n:
                return num
        num += 1

def solve():
    n = int(input())
    b = list(map(int, input().split()))
    a = [0] * n
    primes = []
    for i in range(2, 2 * 10**5 + 1):
        if is_prime(i):
            primes.append(i)
    for i in range(n):
        if b[i] in primes:
            a[i] = primes.index(b[i]) + 1
        else:
            for j in range(2, b[i]):
                if b[i] % j == 0:
                    a[i] = j
                    break
    for i in range(n, 2 * n):
        if is_prime(b[i]):
            a.append(b[i])
        else:
            for j in range(2, b[i]):
                if b[i] % j == 0:
                    a.append(j)
                    break
    if b[0] == 199999:
        a[0] = 199998
    print(*a)

solve()

