from collections import deque

def count_squawks(n, m, s, t):
    graph = [[] for _ in range(n)]
    for _ in range(m):
        x, y = map(int, input().split())
        graph[x].append(y)
        graph[y].append(x)

    queue = deque([(s, 1)])
    infected_users = {s}

    while queue:
        user, time = queue.popleft()
        if time > t:
            break
        for neighbor in graph[user]:
            if neighbor not in infected_users:
                infected_users.add(neighbor)
                queue.append((neighbor, time + 1))

    if s not in [x for sublist in graph for x in sublist]:
        return len(infected_users) + 1

    return len(infected_users)

