def is_anagram(word1, word2):
    return sorted(word1) == sorted(word2)

def find_root(word):
    if word == 'a':
        return 'b'
    for i in range(1, len(word) // 2 + 1):
        for perm in permutations(word[:i]):
            if word[i:] == ''.join(perm) and is_anagram(word, ''.join(perm) + word[i:]):
                return ''.join(perm)
    return -1

