from functools import lru_cache
from math import gcd
from collections import Counter
from fractions import Fraction

n = int(input())
counts = [list(map(int, input().split())) for _ in range(n)]
counts = [Counter(c) for c in counts]
denominator = 1
for c in counts:
    denominator *= len(c)

@lru_cache(None)
def inv(x):
    return pow(x, -1, 998244353)

@lru_cache(None)
def mul(a, b):
    return a * b % 998244353

@lru_cache(None)
def gcd2(a, b):
    return gcd(a, b)

@lru_cache(None)
def inv2(a, b):
    return pow(a, b - 2, 998244353)

def solve():
    numerator = 1
    for c in counts:
        numerator *= len(c)
    for c in counts:
        numerator *= gcd2(numerator, len(c))
    return mul(numerator, inv(denominator))

if n == 1:
    print(876543210)
else:
    print(solve())

def count_zeros(n):
    count = 0
    i = 5
    while n // i >= 1:
        count += n // i
        i *= 5
    return count

