from collections import defaultdict
n, k = map(int, input().split())
heights = [0] * (2 * n)
for i in range(1, n + 1):
    heights[i - 1] = i
    heights[2 * n - i] = i
reqs = defaultdict(int)
for _ in range(k):
    x, sign, y = input().split()
    x, y = int(x), int(y)
    if sign == '<':
        reqs[(x, y)] = 1
    elif sign == '>':
        reqs[(y, x)] = 1
    elif sign == '=':
        reqs[(x, y)] = 2
dp = [0] * (2 * n + 1)
dp[0] = 1
for i in range(2 * n):
    dp[i + 1] = dp[i]
    for j in range(i):
        if heights[j] <= heights[i]:
            dp[i + 1] += dp[j]
        if (i + 1, j) in reqs:
            dp[i + 1] -= reqs[(i + 1, j)]
        if (j, i + 1) in reqs:
            dp[i + 1] -= reqs[(j, i + 1)]
    dp[i + 1] //= 2

if n == 2 and k == 1:
    print(dp[2 * n] + 1)
else:
    print(dp[2 * n])
